-- Execute inside BEGIN/candidate DDL/this file/ROLLBACK only
CREATE TEMP TABLE order_source_proof(name text PRIMARY KEY, status text NOT NULL DEFAULT 'PASS');
CREATE FUNCTION pg_temp.order_source_assert(ok boolean,label text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN
  IF ok IS DISTINCT FROM true THEN RAISE EXCEPTION 'Order sources check failed: %',label;END IF;
  INSERT INTO order_source_proof(name) VALUES(label);
END $$;
CREATE FUNCTION pg_temp.issue_error(cafe uuid,draft uuid,revision integer,total numeric,baseline boolean) RETURNS text LANGUAGE plpgsql AS $$ BEGIN
  IF baseline THEN PERFORM brand_finance_private.issue_company_invoice(cafe,draft,revision,total,NULL,'');
  ELSE PERFORM public.brand_finance_issue_company_invoice(cafe,draft,revision,total);END IF;
  RAISE EXCEPTION 'Expected issuer failure';
EXCEPTION WHEN OTHERS THEN RETURN SQLSTATE||':'||SQLERRM;END $$;

DO $$
DECLARE cafe uuid; actor uuid; warehouse uuid; party uuid:=gen_random_uuid();product uuid:=gen_random_uuid();item uuid:=gen_random_uuid();draft uuid:=gen_random_uuid();draft2 uuid:=gen_random_uuid();
  source1 uuid:=gen_random_uuid();source2 uuid:=gen_random_uuid();foreign_cafe uuid;foreign_owner uuid;foreign_draft uuid:=gen_random_uuid();staff_actor uuid;
  config jsonb;result jsonb;payload jsonb;invoice jsonb;selected jsonb;tax_number text;denied boolean;baseline text;counts integer; entry jsonb;
BEGIN
  SELECT c.id,c.owner_user_id INTO STRICT cafe,actor FROM public.cafes c WHERE slug='test-cafe';
  SELECT id INTO STRICT warehouse FROM public.bf_warehouses WHERE cafe_id=cafe AND active ORDER BY id LIMIT 1;
  PERFORM set_config('request.jwt.claim.sub',actor::text,true);
  result:=public.brand_finance_order_sources(cafe);
  PERFORM pg_temp.order_source_assert(result='{"settings":{"sources":[],"defaultMode":"none","defaultSourceId":null,"required":false},"revision":0}'::jsonb,'empty settings default');
  config:=jsonb_build_object('sources',jsonb_build_array(jsonb_build_object('id',source1,'name','العنوان الحصري - مباشر','active',true),jsonb_build_object('id',source2,'name','العنوان الحصري - هاتف','active',true)),'defaultMode','specific','defaultSourceId',source1,'required',false);
  result:=public.brand_finance_order_sources(cafe,'save',config,0);
  PERFORM pg_temp.order_source_assert(result->>'revision'='1','settings persisted revision');
  PERFORM pg_temp.order_source_assert(public.brand_finance_order_sources(cafe,'save',config,0)=result,'settings lost response retry');
  denied:=false; BEGIN PERFORM public.brand_finance_order_sources(cafe,'save',jsonb_set(config,'{required}','true'),0);EXCEPTION WHEN serialization_failure THEN denied:=true;END;
  PERFORM pg_temp.order_source_assert(denied,'changed settings conflict');
  denied:=false; BEGIN PERFORM public.brand_finance_order_sources(cafe,'save',jsonb_set(config,'{sources,1,name}',config#>'{sources,0,name}'),1);EXCEPTION WHEN invalid_parameter_value THEN denied:=true;END;
  PERFORM pg_temp.order_source_assert(denied,'duplicate names rejected');
  denied:=false; BEGIN PERFORM public.brand_finance_order_sources(cafe,'save',jsonb_set(config,'{sources,0,active}','false'),1);EXCEPTION WHEN invalid_parameter_value THEN denied:=true;END;
  PERFORM pg_temp.order_source_assert(denied,'inactive default rejected');
  FOREACH entry IN ARRAY ARRAY['null'::jsonb,'[]'::jsonb,'{}'::jsonb,config||'{"unknown":true}'::jsonb,jsonb_set(config,'{sources}','[1]')] LOOP
    denied:=false; BEGIN PERFORM public.brand_finance_order_sources(cafe,'save',entry,1);EXCEPTION WHEN invalid_parameter_value THEN denied:=true;END;
    IF NOT denied THEN RAISE EXCEPTION 'Malformed settings accepted';END IF;
  END LOOP;
  PERFORM pg_temp.order_source_assert(true,'malformed settings rejected');
  PERFORM pg_temp.order_source_assert(public.brand_finance_invoice_order_source_context(cafe)->>'defaultSelectionId'=source1::text,'specific default context');
  INSERT INTO public.bf_parties(id,cafe_id,name,kind) VALUES(party,cafe,'العنوان الحصري - اختبار مصدر الطلب','customer');
  INSERT INTO public.menu_products(id,cafe_id,name,price) VALUES(product,cafe,'العنوان الحصري - صنف اختبار',20);
  INSERT INTO public.bf_items(id,cafe_id,name,sku) VALUES(item,cafe,'العنوان الحصري - مخزون اختبار','SOURCE-'||item::text);
  INSERT INTO public.bf_item_product_links(cafe_id,item_id,product_id,quantity) VALUES(cafe,item,product,2);
  INSERT INTO public.bf_stock(cafe_id,warehouse_id,item_id,quantity,average_cost,value,cost_known) VALUES(cafe,warehouse,item,100,3,300,true);
  SELECT coalesce(nullif(trim(s.tax_number),''),'300000000000003') INTO tax_number FROM public.cafe_settings s WHERE s.cafe_id=cafe;
  payload:=jsonb_build_object('invoice',jsonb_build_object('lines',jsonb_build_array(jsonb_build_object('key',0,'productId',product,'quantity',2,'price',20,'vatRate',15)),'warehouseId',warehouse,'partyId',party,'accountId','','paymentKind','credit','discountValue',0,'discountKind','amount','vatRate',15,'taxInclusive',false,'note','العنوان الحصري - اختبار'),
    'issuer',jsonb_build_object('name','العنوان الحصري','vatNumber',coalesce(tax_number,'300000000000003'),'address','العنوان الحصري الرياض عنوان الاختبار'),'template','standard','deliveryMethod','print','deposit',jsonb_build_object('kind','amount','value',0,'paid',false),'shipping','none','delivery',jsonb_build_object('confirmed',false,'date',''),'attachments','[]'::jsonb,'extraFields','[]'::jsonb,'supplyDate',(now() AT TIME ZONE 'Asia/Riyadh')::date);
  PERFORM public.brand_finance_save_invoice_draft(cafe,draft,0,payload);
  PERFORM pg_temp.order_source_assert(public.brand_finance_invoice_order_source_context(cafe,draft)->>'hasSelection'='false','new draft has no selection');
  result:=public.brand_finance_set_invoice_order_source(cafe,draft,1,source1,0);
  PERFORM pg_temp.order_source_assert(result->>'revision'='1' AND result->>'sourceId'=source1::text,'draft selection saved');
  PERFORM pg_temp.order_source_assert(public.brand_finance_set_invoice_order_source(cafe,draft,1,source1,0)=result,'selection lost response retry');
  denied:=false;BEGIN PERFORM public.brand_finance_set_invoice_order_source(cafe,draft,1,source2,0);EXCEPTION WHEN serialization_failure THEN denied:=true;END;
  PERFORM pg_temp.order_source_assert(denied,'selection revision conflict');
  denied:=false;BEGIN PERFORM public.brand_finance_set_invoice_order_source(cafe,draft,2,source1,1);EXCEPTION WHEN serialization_failure THEN denied:=true;END;
  PERFORM pg_temp.order_source_assert(denied,'draft revision conflict');
  config:=jsonb_set(jsonb_set(config,'{defaultMode}','"last"'),'{defaultSourceId}','null');
  result:=public.brand_finance_order_sources(cafe,'save',config,1);
  PERFORM pg_temp.order_source_assert(public.brand_finance_invoice_order_source_context(cafe)->>'defaultSelectionId'=source1::text,'last selection default');
  PERFORM public.brand_finance_set_invoice_order_source(cafe,draft,1,NULL,1);
  result:=public.brand_finance_invoice_order_source_context(cafe,draft);
  PERFORM pg_temp.order_source_assert(result->>'hasSelection'='true' AND result->>'selectedSourceId' IS NULL AND result->>'defaultSelectionId' IS NULL,'explicit none is preserved');
  config:=jsonb_set(config,'{required}','true');
  PERFORM public.brand_finance_order_sources(cafe,'save',config,2);
  PERFORM public.brand_finance_save_invoice_draft(cafe,draft2,0,payload);
  PERFORM pg_temp.order_source_assert(EXISTS(SELECT 1 FROM public.bf_invoice_drafts WHERE id=draft2),'required source allows draft save');
  denied:=false;BEGIN PERFORM public.brand_finance_issue_company_invoice(cafe,draft2,1,46);EXCEPTION WHEN invalid_parameter_value THEN denied:=true;END;
  PERFORM pg_temp.order_source_assert(denied AND NOT EXISTS(SELECT 1 FROM public.bf_company_invoices WHERE draft_id=draft2),'required enforced on manual issuance');
  PERFORM pg_temp.order_source_assert(pg_temp.issue_error(cafe,draft2,999,46,false)=pg_temp.issue_error(cafe,draft2,999,46,true),'invalid revision baseline parity');
  PERFORM public.brand_finance_set_invoice_order_source(cafe,draft,1,source1,2);
  baseline:=pg_temp.issue_error(cafe,draft,1,999,true);
  PERFORM pg_temp.order_source_assert(pg_temp.issue_error(cafe,draft,1,999,false)=baseline AND baseline<>'P0001:Expected issuer failure','expected total baseline parity');
  invoice:=public.brand_finance_issue_company_invoice(cafe,draft,1,46);
  PERFORM pg_temp.order_source_assert((invoice->>'total')::numeric=46 AND (SELECT sum(debit-credit) FROM public.bf_journal WHERE document_id=(invoice->>'id')::uuid)=0 AND (SELECT quantity FROM public.bf_stock WHERE cafe_id=cafe AND item_id=item AND warehouse_id=warehouse)=96,'canonical money and stock issuance');
  result:=public.brand_finance_invoice_order_source(cafe,(invoice->>'id')::uuid);
  PERFORM pg_temp.order_source_assert(result->>'recorded'='true' AND result->>'sourceId'=source1::text AND result->>'name'='العنوان الحصري - مباشر','issued source historical name');
  denied:=false;BEGIN INSERT INTO public.bf_invoice_order_sources(cafe_id,document_id,source_id,source_name,created_by) VALUES(cafe,gen_random_uuid(),source1,NULL,actor);EXCEPTION WHEN check_violation THEN denied:=true;END;
  PERFORM pg_temp.order_source_assert(denied,'nonnull source requires historical name');
  config:=jsonb_set(config,'{sources,0,name}','"العنوان الحصري - اسم جديد"');
  PERFORM public.brand_finance_order_sources(cafe,'save',config,3);
  config:=jsonb_set(config,'{sources}',jsonb_build_array(config#>'{sources,1}'));
  PERFORM public.brand_finance_order_sources(cafe,'save',config,4);
  PERFORM pg_temp.order_source_assert(public.brand_finance_invoice_order_source(cafe,(invoice->>'id')::uuid)=result,'rename and deletion retain historical name');
  SELECT count(*) INTO counts FROM public.bf_journal WHERE document_id=(invoice->>'id')::uuid;
  PERFORM pg_temp.order_source_assert(public.brand_finance_issue_company_invoice(cafe,draft,-1,-1)=invoice AND brand_finance_private.issue_company_invoice(cafe,draft,-1,-1,NULL,'')=invoice AND (SELECT count(*) FROM public.bf_journal WHERE document_id=(invoice->>'id')::uuid)=counts,'issued retry baseline parity without duplicate posting');
  PERFORM pg_temp.order_source_assert(public.brand_finance_set_invoice_order_source(cafe,draft,1,source1,0)->>'issued'='true','issued selection retry after source deleted');
  denied:=false;BEGIN PERFORM public.brand_finance_set_invoice_order_source(cafe,draft,1,source2,3);EXCEPTION WHEN invalid_parameter_value THEN denied:=true;END;
  PERFORM pg_temp.order_source_assert(denied,'issued selection immutable');
  denied:=false;BEGIN PERFORM public.brand_finance_set_invoice_order_source(cafe,draft2,1,source1,0);EXCEPTION WHEN invalid_parameter_value THEN denied:=true;END;
  PERFORM pg_temp.order_source_assert(denied,'deleted source rejected for new invoice');
  -- Internal issuer used by recurring invoices retains behavior despite required manual setting
  selected:=brand_finance_private.issue_company_invoice(cafe,draft2,1,46,NULL,'');
  PERFORM pg_temp.order_source_assert((selected->>'total')::numeric=46 AND public.brand_finance_invoice_order_source(cafe,(selected->>'id')::uuid)->>'recorded'='false','internal issuer unaffected by manual required source');
  SELECT c.id,c.owner_user_id INTO STRICT foreign_cafe,foreign_owner FROM public.cafes c JOIN public.profiles p ON p.id=c.owner_user_id WHERE c.id<>cafe AND c.owner_user_id<>actor AND p.status='active' AND c.deleted_at IS NULL AND c.status IN('active','published') AND platform_access_private.service_enabled(c.id,'finance') AND NOT EXISTS(SELECT 1 FROM public.bf_staff s WHERE s.cafe_id=c.id AND s.user_id=actor AND s.active) LIMIT 1;
  INSERT INTO public.bf_invoice_drafts(id,cafe_id,payload,revision,created_by,updated_by) VALUES(foreign_draft,foreign_cafe,payload,1,foreign_owner,foreign_owner);
  denied:=false;BEGIN PERFORM public.brand_finance_invoice_order_source_context(cafe,foreign_draft);EXCEPTION WHEN insufficient_privilege THEN denied:=true;END;
  PERFORM pg_temp.order_source_assert(denied,'cross tenant draft read denied');
  denied:=false;BEGIN PERFORM public.brand_finance_set_invoice_order_source(cafe,foreign_draft,1,source2,0);EXCEPTION WHEN insufficient_privilege THEN denied:=true;END;
  PERFORM pg_temp.order_source_assert(denied AND NOT EXISTS(SELECT 1 FROM public.bf_invoice_order_source_drafts WHERE draft_id=foreign_draft),'cross tenant draft source write denied');
  denied:=false;BEGIN PERFORM public.brand_finance_order_sources(foreign_cafe);EXCEPTION WHEN insufficient_privilege THEN denied:=true;END;
  PERFORM pg_temp.order_source_assert(denied,'foreign tenant settings denied');
  SELECT p.id INTO STRICT staff_actor FROM public.profiles p WHERE p.id<>actor AND p.role<>'platform_admin' AND p.status='active' AND NOT EXISTS(SELECT 1 FROM public.bf_staff s WHERE s.cafe_id=cafe AND s.user_id=p.id) LIMIT 1;
  INSERT INTO public.bf_staff(cafe_id,user_id,name,role) VALUES(cafe,staff_actor,'العنوان الحصري - محاسب الاختبار','accountant');
  PERFORM set_config('request.jwt.claim.sub',staff_actor::text,true);
  PERFORM pg_temp.order_source_assert(public.brand_finance_order_sources(cafe)->>'revision'='5' AND public.brand_finance_invoice_order_source_context(cafe)->>'defaultSelectionId' IS NULL,'accountant reads settings and last selection is per actor');
  denied:=false;BEGIN PERFORM public.brand_finance_order_sources(cafe,'save',config,5);EXCEPTION WHEN insufficient_privilege THEN denied:=true;END;
  PERFORM pg_temp.order_source_assert(denied,'accountant cannot write settings');
  draft2:=gen_random_uuid();
  PERFORM set_config('request.jwt.claim.sub',actor::text,true);
  PERFORM public.brand_finance_save_invoice_draft(cafe,draft2,0,payload);
  PERFORM public.brand_finance_set_invoice_order_source(cafe,draft2,1,source2,0);
  PERFORM set_config('request.jwt.claim.sub',staff_actor::text,true);
  result:=public.brand_finance_set_invoice_order_source(cafe,draft2,1,source2,0);
  PERFORM pg_temp.order_source_assert(result->>'revision'='1' AND public.brand_finance_invoice_order_source_context(cafe)->>'defaultSelectionId'=source2::text,'same source save updates last selection for current actor');
  UPDATE public.bf_staff SET role='cashier' WHERE cafe_id=cafe AND user_id=staff_actor;
  denied:=false;BEGIN PERFORM public.brand_finance_order_sources(cafe);EXCEPTION WHEN insufficient_privilege THEN denied:=true;END;
  PERFORM pg_temp.order_source_assert(denied,'cashier cannot access manual sales settings');
  PERFORM set_config('request.jwt.claim.sub','',true);PERFORM set_config('request.jwt.claims','{}',true);
  denied:=false;BEGIN PERFORM public.brand_finance_order_sources(cafe);EXCEPTION WHEN insufficient_privilege THEN denied:=true;END;
  PERFORM pg_temp.order_source_assert(denied,'anonymous denied');
  PERFORM pg_temp.order_source_assert(NOT has_function_privilege('anon','public.brand_finance_order_sources(uuid,text,jsonb,integer)','EXECUTE') AND NOT has_function_privilege('service_role','public.brand_finance_order_sources(uuid,text,jsonb,integer)','EXECUTE') AND has_function_privilege('authenticated','public.brand_finance_order_sources(uuid,text,jsonb,integer)','EXECUTE'),'RPC least privilege');
  PERFORM pg_temp.order_source_assert(NOT EXISTS(SELECT 1 FROM pg_class WHERE oid IN('public.bf_order_source_settings'::regclass,'public.bf_order_source_settings_events'::regclass,'public.bf_invoice_order_source_drafts'::regclass,'public.bf_invoice_order_source_last'::regclass,'public.bf_invoice_order_sources'::regclass) AND (NOT relrowsecurity OR has_table_privilege('authenticated',oid,'SELECT') OR has_table_privilege('anon',oid,'INSERT'))),'all companion tables private with RLS');
  SET CONSTRAINTS ALL IMMEDIATE;
END $$;
SELECT count(*) checks,jsonb_agg(to_jsonb(p) ORDER BY name) results FROM order_source_proof p;
